/**
 * CardList FSM - Finite State Machine for card list selection behavior
 *
 * Manages selection logic for card lists with three modes:
 * - none: No selection allowed (display only)
 * - single: Only one card can be selected at a time (radio-like)
 * - multiple: Multiple cards can be selected (checkbox-like)
 *
 * This FSM is pure and testable - no React dependencies.
 * The component uses useReducer with this reducer.
 *
 * @module CardList/FSM
 */

// =============================================================================
// Types
// =============================================================================

/**
 * Selection mode for CardList
 */
export type CardListSelectionMode = 'none' | 'single' | 'multiple';

/**
 * Visual state for the CardList - used for CSS styling and accessibility
 */
export type CardListVisualState = 'none' | 'one' | 'some' | 'all';

/**
 * FSM state for CardList
 */
export interface CardListFSMState {
  /** Currently selected values (empty for 'none' mode) */
  selectedValues: string[];
  /** Derived visual state based on selection count */
  visualState: CardListVisualState;
}

// =============================================================================
// Event Types
// =============================================================================

/**
 * Reset state from controlled props - used when value prop changes
 */
export interface ResetFromPropsEvent {
  type: 'RESET_FROM_PROPS';
  /** New selected values from props */
  values: string[];
  /** Selection mode */
  mode: CardListSelectionMode;
  /** Total count of enabled (non-disabled) cards */
  totalEnabled: number;
}

/**
 * Select a single item (single selection mode only)
 * Replaces the current selection with the new value.
 */
export interface SelectItemEvent {
  type: 'SELECT_ITEM';
  /** Value of the card being selected */
  value: string;
  /** Total count of enabled cards */
  totalEnabled: number;
}

/**
 * Toggle a single item's selection state (multiple selection mode only)
 */
export interface ToggleItemEvent {
  type: 'TOGGLE_ITEM';
  /** Value of the card being toggled */
  value: string;
  /** Total count of enabled cards */
  totalEnabled: number;
}

/**
 * Clear all selections
 */
export interface ClearAllEvent {
  type: 'CLEAR_ALL';
}

/**
 * Select all enabled items (multiple selection mode only)
 */
export interface SelectAllEvent {
  type: 'SELECT_ALL';
  /** Array of all enabled card values */
  enabledValues: string[];
  /** Total count of enabled cards */
  totalEnabled: number;
}

/**
 * Union of all FSM events
 */
export type CardListFSMEvent =
  | ResetFromPropsEvent
  | SelectItemEvent
  | ToggleItemEvent
  | ClearAllEvent
  | SelectAllEvent;

// =============================================================================
// State Derivation
// =============================================================================

/**
 * Derives the visual state from selected values and total enabled count
 *
 * @param selectedValues - Currently selected values
 * @param totalEnabled - Total number of enabled cards
 * @returns The derived visual state
 */
export function deriveVisualState(
  selectedValues: string[],
  totalEnabled: number
): CardListVisualState {
  const count = selectedValues.length;

  // No items selected
  if (count === 0) {
    return 'none';
  }

  // Exactly one item selected
  if (count === 1) {
    return 'one';
  }

  // All enabled items selected
  if (count >= totalEnabled && totalEnabled > 0) {
    return 'all';
  }

  // Some items selected (more than one, but not all)
  return 'some';
}

// =============================================================================
// Initial State Factory
// =============================================================================

/**
 * Creates the initial FSM state
 *
 * @param values - Initial selected values
 * @param mode - Selection mode
 * @param totalEnabled - Total number of enabled cards
 * @returns Initial FSM state
 */
export function createInitialCardListFSMState(
  values: string[],
  mode: CardListSelectionMode,
  totalEnabled: number
): CardListFSMState {
  // For 'none' mode, always start with empty selection
  if (mode === 'none') {
    return {
      selectedValues: [],
      visualState: 'none',
    };
  }

  // For 'single' mode, only allow at most one value
  if (mode === 'single') {
    const firstValue = values[0];
    const selectedValues = firstValue !== undefined ? [firstValue] : [];
    return {
      selectedValues,
      visualState: deriveVisualState(selectedValues, totalEnabled),
    };
  }

  // For 'multiple' mode, deduplicate values
  const selectedValues = [...new Set(values)];
  return {
    selectedValues,
    visualState: deriveVisualState(selectedValues, totalEnabled),
  };
}

// =============================================================================
// FSM Reducer
// =============================================================================

/**
 * Pure reducer for CardList FSM
 *
 * Handles all state transitions:
 * - RESET_FROM_PROPS: Sync state with controlled props
 * - SELECT_ITEM: Select a single card (single mode)
 * - TOGGLE_ITEM: Toggle a card's selection (multiple mode)
 * - CLEAR_ALL: Deselect all cards
 * - SELECT_ALL: Select all enabled cards (multiple mode)
 *
 * @param state - Current FSM state
 * @param event - Event to process
 * @returns New FSM state
 */
export function cardListFSMReducer(
  state: CardListFSMState,
  event: CardListFSMEvent
): CardListFSMState {
  switch (event.type) {
    case 'RESET_FROM_PROPS': {
      const { values, mode, totalEnabled } = event;

      // For 'none' mode, always empty
      if (mode === 'none') {
        return {
          selectedValues: [],
          visualState: 'none',
        };
      }

      // For 'single' mode, only keep first value
      if (mode === 'single') {
        const firstValue = values[0];
        const selectedValues = firstValue !== undefined ? [firstValue] : [];
        return {
          selectedValues,
          visualState: deriveVisualState(selectedValues, totalEnabled),
        };
      }

      // For 'multiple' mode, deduplicate
      const selectedValues = [...new Set(values)];
      return {
        selectedValues,
        visualState: deriveVisualState(selectedValues, totalEnabled),
      };
    }

    case 'SELECT_ITEM': {
      const { value, totalEnabled } = event;

      // Single selection - replace current selection
      // Note: Do not deselect if clicking the already selected item
      // (radio button behavior - can't unselect by clicking)
      if (state.selectedValues.includes(value)) {
        // Already selected, no change
        return state;
      }

      const selectedValues = [value];
      return {
        selectedValues,
        visualState: deriveVisualState(selectedValues, totalEnabled),
      };
    }

    case 'TOGGLE_ITEM': {
      const { value, totalEnabled } = event;
      const selected = new Set(state.selectedValues);

      // Toggle the item
      if (selected.has(value)) {
        selected.delete(value);
      } else {
        selected.add(value);
      }

      const selectedValues = Array.from(selected);
      return {
        selectedValues,
        visualState: deriveVisualState(selectedValues, totalEnabled),
      };
    }

    case 'CLEAR_ALL': {
      return {
        selectedValues: [],
        visualState: 'none',
      };
    }

    case 'SELECT_ALL': {
      const { enabledValues, totalEnabled } = event;
      const selectedValues = [...enabledValues];

      return {
        selectedValues,
        visualState: deriveVisualState(selectedValues, totalEnabled),
      };
    }

    default: {
      // TypeScript exhaustiveness check
      const _exhaustive: never = event;
      return _exhaustive;
    }
  }
}

// =============================================================================
// Event Creators
// =============================================================================

/**
 * Creates a RESET_FROM_PROPS event
 */
export function resetFromPropsEvent(
  values: string[],
  mode: CardListSelectionMode,
  totalEnabled: number
): ResetFromPropsEvent {
  return { type: 'RESET_FROM_PROPS', values, mode, totalEnabled };
}

/**
 * Creates a SELECT_ITEM event (single mode)
 */
export function selectItemEvent(value: string, totalEnabled: number): SelectItemEvent {
  return { type: 'SELECT_ITEM', value, totalEnabled };
}

/**
 * Creates a TOGGLE_ITEM event (multiple mode)
 */
export function toggleItemEvent(value: string, totalEnabled: number): ToggleItemEvent {
  return { type: 'TOGGLE_ITEM', value, totalEnabled };
}

/**
 * Creates a CLEAR_ALL event
 */
export function clearAllEvent(): ClearAllEvent {
  return { type: 'CLEAR_ALL' };
}

/**
 * Creates a SELECT_ALL event (multiple mode)
 */
export function selectAllEvent(enabledValues: string[], totalEnabled: number): SelectAllEvent {
  return { type: 'SELECT_ALL', enabledValues, totalEnabled };
}

// =============================================================================
// Predicates
// =============================================================================

/**
 * Check if no items are selected
 */
export function isNoneSelected(state: CardListFSMState): boolean {
  return state.visualState === 'none';
}

/**
 * Check if exactly one item is selected
 */
export function isOneSelected(state: CardListFSMState): boolean {
  return state.visualState === 'one';
}

/**
 * Check if some items are selected (but not all)
 */
export function isSomeSelected(state: CardListFSMState): boolean {
  return state.visualState === 'some';
}

/**
 * Check if all items are selected
 */
export function isAllSelected(state: CardListFSMState): boolean {
  return state.visualState === 'all';
}

/**
 * Check if a specific value is selected
 */
export function isValueSelected(state: CardListFSMState, value: string): boolean {
  return state.selectedValues.includes(value);
}

/**
 * Get the count of selected items
 */
export function getSelectedCount(state: CardListFSMState): number {
  return state.selectedValues.length;
}

/**
 * CardList Component
 *
 * A high-level component for managing groups of SelectableCards with
 * selection logic. Uses the SelectableCard primitive internally.
 *
 * Features:
 * - Three selection modes: none / single / multiple
 * - Controlled and uncontrolled modes
 * - Proper group-level accessibility (fieldset/legend)
 * - FSM-based state management for predictable behavior
 * - Responsive grid/flex layout options
 *
 * Security Features:
 * - Uses SelectableCard which has safe attribute handling
 * - No dangerouslySetInnerHTML
 * - Props are typed and validated
 *
 * @see https://getbootstrap.com/docs/5.3/components/card/
 * @module CardList
 */

import { forwardRef, memo, useCallback, useEffect, useId, useMemo, useReducer } from 'react';

import { useControllableState } from '../../hooks';
import { cn } from '../../utils';
import { SelectableCard } from '../SelectableCard';

import {
  cardListFSMReducer,
  createInitialCardListFSMState,
  resetFromPropsEvent,
  selectItemEvent,
  toggleItemEvent,
} from './CardList.fsm';

import type { CardListProps } from './CardList.types';

// Development warning for accessibility
const WARN_CACHE_LIMIT = 50;
const warnedLists = new Set<string>();

function warnMissingListLabel(listId: string): void {
  if (
    typeof process !== 'undefined' &&
    // biome-ignore lint/complexity/useLiteralKeys: noPropertyAccessFromIndexSignature requires bracket access
    process.env?.['NODE_ENV'] !== 'production' &&
    !warnedLists.has(listId)
  ) {
    if (warnedLists.size >= WARN_CACHE_LIMIT) {
      const first = warnedLists.values().next().value;
      if (first !== undefined) {warnedLists.delete(first);}
    }
    warnedLists.add(listId);
    console.warn(
      `[DSAi CardList] Missing accessible label. ` +
        `Provide a "label" prop or "aria-label"/"aria-labelledby" for screen reader users. ` +
        `This warning will only appear in development mode.`
    );
  }
}

/**
 * CardList Component
 *
 * Manages a list of SelectableCard components with selection logic.
 *
 * @example
 * ```tsx
 * // Display only (no selection)
 * <CardList
 *   label="Available plans"
 *   items={[
 *     { value: 'basic', title: 'Basic', description: '$9/month' },
 *     { value: 'pro', title: 'Pro', description: '$29/month' },
 *   ]}
 * />
 *
 * // Single selection (radio-like)
 * <CardList
 *   label="Select a plan"
 *   selectionMode="single"
 *   items={plans}
 *   value={selectedPlan}
 *   onChange={setSelectedPlan}
 * />
 *
 * // Multiple selection (checkbox-like)
 * <CardList
 *   label="Select features"
 *   selectionMode="multiple"
 *   items={features}
 *   value={selectedFeatures}
 *   onChange={setSelectedFeatures}
 * />
 * ```
 */
// Use internal type for implementation (more permissive), but expose public discriminated union type
const CardListComponent = forwardRef<HTMLFieldSetElement, CardListProps>(
  (
    {
      items,
      selectionMode = 'none',
      value,
      defaultValue,
      onChange,
      name,
      disabled = false,
      error = false,
      errorMessage,
      required = false,
      size,
      variant = 'outlined',
      selectedColor,
      horizontal = false,
      orientation = 'vertical',
      gap = '0.5rem',
      columns,
      label,
      'aria-label': ariaLabel,
      'aria-labelledby': ariaLabelledby,
      'aria-describedby': externalDescribedby,
      helperText,
      onVisualStateChange,
      renderItem,
      className = '',
      style,
      id: providedId,
      dangerouslySetInnerHTML: _dSIH,
      ...rest
    },
    ref
  ) => {
    // Generate unique IDs
    const generatedId = useId();
    const id = providedId || generatedId;
    const labelId = `${id}-label`;
    const helperId = `${id}-helper`;
    const errorId = `${id}-error`;

    // Ensure radio groups always have a stable name for accessibility
    const computedName = useMemo(() => {
      if (selectionMode === 'single') {
        return name ?? `${id}-group`;
      }
      return name;
    }, [selectionMode, name, id]);

    // Compute enabled items
    const enabledItems = useMemo(
      () => items.filter((item) => !item.disabled && !disabled),
      [items, disabled]
    );
    const enabledValues = useMemo(() => enabledItems.map((item) => item.value), [enabledItems]);
    const totalEnabled = enabledValues.length;

    // Normalize value to array
    const normalizeValue = useCallback((val: string | string[] | undefined): string[] => {
      if (val === undefined) {
        return [];
      }
      if (Array.isArray(val)) {
        return val;
      }
      return [val];
    }, []);

    const normalizedValue = useMemo(
      () => (value !== undefined ? normalizeValue(value) : undefined),
      [value, normalizeValue]
    );

    const normalizedDefaultValue = useMemo(
      () => normalizeValue(defaultValue),
      [defaultValue, normalizeValue]
    );

    // Use centralized hook for controlled/uncontrolled state management
    const [selectedValues, setSelectedValues] = useControllableState<string[]>({
      value: normalizedValue,
      defaultValue: normalizedDefaultValue,
      onChange: (newValues) => {
        if (onChange) {
          // For single mode, return single value or undefined
          if (selectionMode === 'single') {
            onChange(newValues.length > 0 ? newValues[0] : undefined);
          } else {
            // For multiple mode, return array
            onChange(newValues);
          }
        }
      },
    });

    // Initialize FSM state with current selected values
    const [fsmState, dispatch] = useReducer(
      cardListFSMReducer,
      { values: selectedValues, mode: selectionMode, totalEnabled },
      (init) => createInitialCardListFSMState(init.values, init.mode, init.totalEnabled)
    );

    // Sync FSM with current selected values (controlled or uncontrolled)
    useEffect(() => {
      dispatch(resetFromPropsEvent(selectedValues, selectionMode, totalEnabled));
    }, [selectedValues, selectionMode, totalEnabled]);

    // Dev warning for missing accessible label
    useEffect(() => {
      if (!label && !ariaLabel && !ariaLabelledby) {
        warnMissingListLabel(id);
      }
    }, [label, ariaLabel, ariaLabelledby, id]);

    // Handle card selection for single mode
    const handleSelectItem = useCallback(
      (itemValue: string) => {
        // Compute next state
        const nextState = cardListFSMReducer(fsmState, selectItemEvent(itemValue, totalEnabled));
        // Update selected values via hook (handles both controlled and uncontrolled)
        setSelectedValues(nextState.selectedValues);
      },
      [fsmState, totalEnabled, setSelectedValues]
    );

    // Handle card toggle for multiple mode
    const handleToggleItem = useCallback(
      (itemValue: string) => {
        // Compute next state
        const nextState = cardListFSMReducer(fsmState, toggleItemEvent(itemValue, totalEnabled));
        // Update selected values via hook (handles both controlled and uncontrolled)
        setSelectedValues(nextState.selectedValues);
      },
      [fsmState, totalEnabled, setSelectedValues]
    );

    // Handle card selection based on mode
    const handleCardChange = useCallback(
      (itemValue: string, checked: boolean) => {
        if (selectionMode === 'single') {
          // Only handle selection (not deselection) for single mode
          if (checked) {
            handleSelectItem(itemValue);
          }
        } else if (selectionMode === 'multiple') {
          handleToggleItem(itemValue);
        }
      },
      [selectionMode, handleSelectItem, handleToggleItem]
    );

    // Derive visual state for rendering (selectedValues comes from useControllableState)
    const { visualState } = fsmState;
    const renderSelectedValues = fsmState.selectedValues;

    // Notify consumer of visual state changes
    useEffect(() => {
      onVisualStateChange?.(visualState);
    }, [visualState, onVisualStateChange]);

    // Determine selection mode for SelectableCard
    const cardSelectionMode = useMemo(() => {
      switch (selectionMode) {
        case 'none':
          return 'none' as const;
        case 'single':
          return 'radio' as const;
        case 'multiple':
          return 'checkbox' as const;
        default:
          return 'none' as const;
      }
    }, [selectionMode]);

    // Build class names
    const wrapperClasses = useMemo(
      () => cn('card-list', error && 'has-error', className),
      [error, className]
    );

    // Whether columns is a responsive object
    const isResponsiveColumns = typeof columns === 'object';

    // Build container classes based on layout
    const containerClasses = useMemo(() => {
      if (isResponsiveColumns) {
        const classes = ['card-list-container', 'row'];
        if (columns.sm) {classes.push(`row-cols-sm-${columns.sm}`);}
        if (columns.md) {classes.push(`row-cols-md-${columns.md}`);}
        if (columns.lg) {classes.push(`row-cols-lg-${columns.lg}`);}
        if (columns.xl) {classes.push(`row-cols-xl-${columns.xl}`);}
        return classes.join(' ');
      }
      return 'card-list-container';
    }, [columns, isResponsiveColumns]);

    // Build container styles based on layout
    const containerStyle = useMemo<React.CSSProperties>(() => {
      if (isResponsiveColumns) {
        // Bootstrap row handles layout; use gap as inline style
        return { gap };
      }

      const baseStyle: React.CSSProperties = {
        gap,
      };

      if (typeof columns === 'number') {
        baseStyle.display = 'grid';
        baseStyle.gridTemplateColumns = `repeat(${columns}, 1fr)`;
      } else if (orientation === 'horizontal') {
        baseStyle.display = 'flex';
        baseStyle.flexWrap = 'wrap';
      } else {
        baseStyle.display = 'flex';
        baseStyle.flexDirection = 'column';
      }

      return baseStyle;
    }, [gap, columns, orientation, isResponsiveColumns]);

    // Compute describedby
    const computedDescribedby = useMemo(() => {
      const parts: string[] = [];
      if (externalDescribedby) {
        parts.push(externalDescribedby);
      }
      if (helperText) {
        parts.push(helperId);
      }
      if (error && errorMessage) {
        parts.push(errorId);
      }
      return parts.length > 0 ? parts.join(' ') : undefined;
    }, [externalDescribedby, helperText, helperId, error, errorMessage, errorId]);

    // Content inside fieldset
    const content = (
      <>
        {/* Legend */}
        {label && (
          <legend id={labelId} className="card-list-legend fw-semibold mb-2">
            {label}
            {required && selectionMode !== 'none' && <span className="text-danger ms-1">*</span>}
          </legend>
        )}

        {/* Helper text */}
        {helperText && (
          <div id={helperId} className="form-text mb-2">
            {helperText}
          </div>
        )}

        {/* Cards container */}
        <div className={containerClasses} style={containerStyle} data-visual-state={visualState}>
          {items.map((item, index) => {
            const itemId = `${id}-item-${item.value}`;
            const isSelected = renderSelectedValues.includes(item.value);
            const isDisabled = disabled || item.disabled;

            const card = (
              <SelectableCard
                key={item.value}
                id={itemId}
                value={item.value}
                name={selectionMode === 'none' ? undefined : computedName}
                selectionMode={cardSelectionMode}
                checked={isSelected}
                onChange={(checked) => handleCardChange(item.value, checked)}
                disabled={isDisabled}
                required={required}
                error={error}
                variant={variant}
                selectedColor={selectedColor}
                size={size}
                horizontal={horizontal}
                title={renderItem ? undefined : item.title}
                subtitle={renderItem ? undefined : item.subtitle}
                description={renderItem ? undefined : item.description}
                media={renderItem ? undefined : item.media}
                footer={renderItem ? undefined : item.footer}
              >
                {renderItem
                  ? renderItem(item, { checked: isSelected, disabled: isDisabled ?? false, index })
                  : item.children}
              </SelectableCard>
            );

            if (isResponsiveColumns) {
              return (
                <div key={item.value} className="col">
                  {card}
                </div>
              );
            }

            return card;
          })}
        </div>

        {/* Error message */}
        {error && errorMessage && (
          <div id={errorId} className="invalid-feedback d-block mt-2">
            {errorMessage}
          </div>
        )}
      </>
    );

    return (
      <fieldset
        ref={ref}
        {...rest}
        id={id}
        aria-labelledby={ariaLabelledby}
        aria-label={!label && !ariaLabelledby ? ariaLabel : undefined}
        aria-describedby={computedDescribedby}
        aria-invalid={error || undefined}
        className={wrapperClasses}
        style={style}
        disabled={disabled}
      >
        {content}
      </fieldset>
    );
  }
);

CardListComponent.displayName = 'CardList';

// Memoize component and cast to public type for better DX
// The internal type is more permissive to allow easy implementation,
// but the public type provides discriminated union for type safety
export const CardList = memo(CardListComponent) as React.MemoExoticComponent<
  React.ForwardRefExoticComponent<CardListProps & React.RefAttributes<HTMLFieldSetElement>>
>;

// Preserve displayName through memo wrapper
CardList.displayName = 'CardList';

/**
 * CardList Component Type Definitions
 *
 * This module provides discriminated union types for CardList to ensure
 * type-safe usage in single vs multiple selection modes.
 *
 * @example
 * ```tsx
 * // Single mode - TypeScript knows onChange receives string | undefined
 * <CardList
 *   selectionMode="single"
 *   value={selected}
 *   onChange={(val) => setSelected(val)} // val: string | undefined
 * />
 *
 * // Multiple mode - TypeScript knows onChange receives string[]
 * <CardList
 *   selectionMode="multiple"
 *   value={selected}
 *   onChange={(vals) => setSelected(vals)} // vals: string[]
 * />
 * ```
 *
 * @module CardList/Types
 */

import type { CardListSelectionMode, CardListVisualState } from './CardList.fsm';
import type { CardColor, CardSize, CardVariant } from '../Card/Card.types';
import type { FieldsetHTMLAttributes, ReactNode } from 'react';

// =============================================================================
// CardListItem - Option type for CardList items
// =============================================================================

/**
 * Configuration for a single item in the CardList
 */
export interface CardListItem {
  /** Unique value for this item */
  value: string;
  /** Card title */
  title?: string;
  /** Card subtitle */
  subtitle?: string;
  /** Card description */
  description?: string;
  /** Media element (image, icon, etc.) */
  media?: ReactNode;
  /** Footer content */
  footer?: ReactNode;
  /** Custom children to render instead of title/description */
  children?: ReactNode;
  /** Whether this item is disabled */
  disabled?: boolean;
}

// =============================================================================
// CardListProps - Base and Mode-Specific Types
// =============================================================================

/**
 * Base props shared across all CardList modes
 */
interface CardListBaseProps extends Omit<FieldsetHTMLAttributes<HTMLFieldSetElement>, 'onChange'> {
  // ===========================================================================
  // Items
  // ===========================================================================

  /**
   * Array of card items to render
   */
  items: CardListItem[];

  /**
   * Name attribute for form submission (used for radio/checkbox inputs)
   */
  name?: string;

  // ===========================================================================
  // States
  // ===========================================================================

  /**
   * Whether all cards in the list are disabled
   * @default false
   */
  disabled?: boolean;

  /**
   * Whether the CardList is in an error state
   * @default false
   */
  error?: boolean;

  /**
   * Error message to display
   */
  errorMessage?: string;

  /**
   * Whether selection is required
   * @default false
   */
  required?: boolean;

  // ===========================================================================
  // Visual
  // ===========================================================================

  /**
   * Card size variant for all cards in the list
   */
  size?: CardSize;

  /**
   * Card variant for all cards in the list
   * @default 'outlined'
   */
  variant?: CardVariant;

  /**
   * Card color when selected
   */
  selectedColor?: CardColor;

  /**
   * Whether to display cards horizontally
   * @default false
   */
  horizontal?: boolean;

  /**
   * Layout direction for the list
   * @default 'vertical'
   */
  orientation?: 'horizontal' | 'vertical';

  /**
   * Gap between cards (CSS value)
   * @default '0.5rem'
   */
  gap?: string;

  /**
   * Number of columns for grid layout (responsive)
   * If not set, cards flow naturally based on orientation
   */
  columns?: number | { sm?: number; md?: number; lg?: number; xl?: number };

  // ===========================================================================
  // Accessibility
  // ===========================================================================

  /**
   * Visible label for the CardList (renders as legend in fieldset)
   */
  label?: string;

  /**
   * ARIA label for the CardList (if no visible label)
   */
  'aria-label'?: string;

  /**
   * ID of element that labels this CardList
   */
  'aria-labelledby'?: string;

  /**
   * Helper text to display below the label
   */
  helperText?: string;

  /**
   * Callback fired when the visual state changes (none, one, some, all)
   */
